INSERT INTO products (name,category,description,price,image,featured,stock,tasting_notes,weight,origin,brewing_guide) VALUES
('Royal Ceylon Black','BLACK TEA','A bold, full-bodied black tea powder with the classic depth of high-grown Ceylon tea.',890,'product-black.jpg',1,60,'Malty depth, warm aroma and a clean, brisk finish.','250 g','Nuwara Eliya, Sri Lanka','Use 1–2 tsp per cup. Brew with hot water for 3–5 minutes. Add milk or enjoy black.'),
('Emerald Green Tea','GREEN TEA','A fresh and refined green tea with a clean character and delicate natural aroma.',980,'product-green.jpg',1,48,'Fresh grassy notes, gentle sweetness and a clean finish.','200 g','Kandy, Sri Lanka','Use 1 tsp per cup. Brew with hot water for 2–3 minutes; avoid boiling water for a softer cup.'),
('Golden Ginger Infusion','GINGER TEA','A warming tea blend with a bright ginger aroma, created for comforting everyday moments.',920,'product-ginger.jpg',1,45,'Warm ginger spice, citrus-like brightness and a smooth finish.','250 g','Sri Lanka','Use 1–2 tsp per cup and steep 4–5 minutes. Enjoy plain or with a little honey.'),
('Ceylon Cinnamon Reserve','CINNAMON TEA','A fragrant cinnamon-forward blend balancing natural spice with smooth Ceylon tea.',960,'product-cinnamon.jpg',1,42,'Sweet cinnamon spice, soft tea depth and a lingering aromatic finish.','250 g','Central Highlands, Sri Lanka','Use 1–2 tsp per cup. Steep 3–5 minutes and serve warm.'),
('Serene Herbal Blend','HERBAL TEA','A caffeine-free inspired herbal blend with a light, refreshing character.',880,'herbal-tea.jpg',0,35,'Soft herbal aroma, mellow body and refreshing finish.','200 g','Sri Lanka','Use 1–2 tsp per cup. Steep 5 minutes and adjust strength to taste.'),
('Noir Signature Ceylon','PREMIUM TEA','Our signature premium Ceylon tea powder selected for aroma, balance and an elegant cup.',1290,'premium-tea.jpg',1,28,'Layered aroma, balanced richness and a refined Ceylon finish.','250 g','Nuwara Eliya, Sri Lanka','Use 1 tsp per cup. Brew 3–4 minutes for a balanced premium cup.'),
('Highland Breakfast Tea','BLACK TEA','A dependable breakfast blend with rich colour and a lively finish.',940,'black-tea.jpg',0,55,'Bright briskness, rich body and a classic breakfast character.','500 g','Dimbula, Sri Lanka','Use 2 tsp for a strong pot. Brew 4 minutes and serve with or without milk.'),
('Jasmine Green Reserve','GREEN TEA','A delicate green tea profile paired with a floral-inspired jasmine aroma.',1090,'green-tea.jpg',0,32,'Floral aroma, fresh green character and a delicate finish.','200 g','Central Sri Lanka','Use 1 tsp per cup. Brew 2–3 minutes with hot, not boiling, water.'),
('Spiced Ginger Gold','GINGER TEA','A richer ginger tea profile for customers who enjoy a stronger warming spice note.',990,'ginger-tea.jpg',0,38,'Pronounced ginger warmth, rounded sweetness and a long finish.','250 g','Sri Lanka','Use 1–2 tsp per cup. Steep 4–5 minutes.'),
('Cinnamon Noir Blend','CINNAMON TEA','A premium dark tea and cinnamon combination with an elegant aromatic profile.',1040,'cinnamon-tea.jpg',0,30,'Deep tea body, sweet spice and a smooth lingering aroma.','250 g','Uva, Sri Lanka','Use 1–2 tsp per cup. Brew 3–5 minutes and serve hot.');
